package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"
var WsLeapFlag string = "N"
var WsQ int64 = 0
var WsR4 int64 = 0
var WsR100 int64 = 0
var WsR400 int64 = 0
var WsMaxDay int64 = 0
var WsValid int64 = 0
var WsBadMonth int64 = 0
var WsBadDay int64 = 0

var curRec DateRec
var inputRecords []string
var inputIndex int

func pow10Int64(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func truncateToPic(v int64, digits int) int64 {
	mod := pow10Int64(digits)
	if v >= 0 {
		return v % mod
	}
	return -((-v) % mod)
}

func formatPic9(v int64, width int) string {
	mod := pow10Int64(width)
	av := v % mod
	if av < 0 {
		av = -av
	}
	return fmt.Sprintf("%0*d", width, av)
}

func parsePic9(s string, digits int) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	v, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return 0
	}
	return truncateToPic(v, digits)
}

func parseDateRec(line string) {
	rawId := line[0:4]
	curRec.DtId = rawId
	rawY := line[4:8]
	curRec.DtYyyy = parsePic9(rawY, 4)
	rawM := line[8:10]
	curRec.DtMm = parsePic9(rawM, 2)
	rawD := line[10:12]
	curRec.DtDd = parsePic9(rawD, 2)
}

func isInputDone() bool { return WsEofFlag == "Y" }
func isLeap() bool      { return WsLeapFlag == "Y" }

func loadInput() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if len(data) == 0 {
		inputRecords = []string{}
		return
	}
	s := strings.ReplaceAll(string(data), "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	parts := strings.Split(s, "\n")
	if len(s) > 0 && s[len(s)-1] == '\n' {
		if len(parts) > 0 && parts[len(parts)-1] == "" {
			parts = parts[:len(parts)-1]
		}
	}
	inputRecords = parts
}

func ReadPara() {
	if inputIndex >= len(inputRecords) {
		WsEofFlag = "Y"
		return
	}
	line := inputRecords[inputIndex]
	inputIndex++
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	parseDateRec(line)
}

func LeapPara() {
	q := curRec.DtYyyy / 4
	r := curRec.DtYyyy % 4
	WsQ = truncateToPic(q, 4)
	WsR4 = truncateToPic(r, 3)

	q = curRec.DtYyyy / 100
	r = curRec.DtYyyy % 100
	WsQ = truncateToPic(q, 4)
	WsR100 = truncateToPic(r, 3)

	q = curRec.DtYyyy / 400
	r = curRec.DtYyyy % 400
	WsQ = truncateToPic(q, 4)
	WsR400 = truncateToPic(r, 3)

	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DaysPara() {
	switch curRec.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = truncateToPic(29, 2)
		} else {
			WsMaxDay = truncateToPic(28, 2)
		}
	case 4, 6, 9, 11:
		WsMaxDay = truncateToPic(30, 2)
	default:
		WsMaxDay = truncateToPic(31, 2)
	}
}

func ProcessPara() {
	LeapPara()
	if curRec.DtMm < 1 || curRec.DtMm > 12 {
		WsBadMonth = truncateToPic(WsBadMonth+1, 2)
		fmt.Printf("%s BAD MONTH %s\n", curRec.DtId, formatPic9(curRec.DtMm, 2))
	} else {
		DaysPara()
		if curRec.DtDd < 1 || curRec.DtDd > WsMaxDay {
			WsBadDay = truncateToPic(WsBadDay+1, 2)
			fmt.Printf("%s BAD DAY %s MAX %s\n", curRec.DtId, formatPic9(curRec.DtDd, 2), formatPic9(WsMaxDay, 2))
		} else {
			WsValid = truncateToPic(WsValid+1, 2)
			fmt.Printf("%s VALID %s-%s-%s\n", curRec.DtId, formatPic9(curRec.DtYyyy, 4), formatPic9(curRec.DtMm, 2), formatPic9(curRec.DtDd, 2))
		}
	}
	ReadPara()
}

func MainPara() {
	loadInput()
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	fmt.Printf("VALID: %s BAD MONTH: %s BAD DAY: %s\n", formatPic9(WsValid, 2), formatPic9(WsBadMonth, 2), formatPic9(WsBadDay, 2))
}

func main() {
	MainPara()
}
